// TH15 v1.00b Stage 6 boss nonspell 1 (st06bs.ecl.txt Boss1 + Boss1_at).
// Synthetic shell: control is the phase host; the real Boss is invincible and keeps the
// source body/hurt boxes, limit rectangle and movement. No DPS drives the attack.

const TIME_LIMIT: int = 2524;   // 120 opening buffer + 2400 source timeout + 4 startup slack
const OPENING_BUFFER: int = 120;

// Source etSprite type 5; TH15 synthetic alias for the existing modern slot (radius 4).
const TH15_BALL2: int = 432;

const RING_SPEED: fx = 2fx;      // etSpeed(0, 2.0f, 0.2f) with layers=1 -> s0 only
const RING_DIST: fx = 24fx;      // etDist(0, 24.0f)
const BOSS_X: fx = 0fx;          // Boss context: movePos(0.0f, 128.0f)
const BOSS_Y: fx = 128fx;

// VELTIME (type 0x200000): a=120 frames, r=4/6/7/8 (rank), s=-999999 keeps the angle.
// No later effect reads the native logical scalar, so a linear speed STEP is equivalent.
xformdef SPEED_RAMP(target: fx) {
    @30 add_speed(0fx);
    step_speed(target, 120 + 65536 * EASE_LINEAR);
}

// Source Boss1_at: etNew(0); etAim(0,3) fixed full ring; etSprite(0,5,6);
// etCount(0,N,1); etSpeed(0,2,0.2); etAngle(0,pi/2,0); etDist(0,24); etOn(0).
sub boss_fire(shots: int, target: fx) {
    sh_reset(0);
    sh_sprite(0, TH15_BALL2, 6);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, shots, 1);
    sh_speed(0, RING_SPEED, 0fx);
    sh_angle(0, 90deg, 0deg);
    sh_dist(0, RING_DIST);
    sh_xform(0, SPEED_RAMP(target));
    sh_fire(0);
}

// moveRand(60, 4, 1.9): the angle mode does not override the inherited mode0 (linear)
// speed slot, so speed(k) = 1.9*(60-k)/60 for k=1..60. Direction is drawn once per call.
// Shared enemy state owned by this card: int slot 0 = step count, fx slots 0/1 = unit dir.
// Limit rectangle moveLimit(0,128,280,8): x in [-140,140], y in [124,132]; the direction
// inner region is center +- width/4 / height/4 -> |x|<=70, y in [126,130].
sub boss_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 1.9fx * ((60 - k) as fx) / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 124fx { ny = 124fx; }
    if ny > 132fx { ny = 132fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub boss_begin_rand() {
    var r: int = rand(65536) - 32768;   // signed pi unit, BAM
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var pick: int = rand(65536) % 3;
        if $player_x > $self_x {
            if pick == 0 { a = a + 32768; }
        } else {
            if pick != 0 { a = a + 32768; }
        }
    }
    if $self_y < 126fx {
        if a < 0 { a = -a; }
    } else if $self_y > 130fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad, nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    boss_arm_next_step();
}

// The 60 source movement ticks run under the loop tail wait(60); stage 5 integrates the
// armed displacement, so the next source tick is pre-armed here without a separate task.
sub boss_wait_move(frames: int) {
    for i in 0..frames {
        wait(1);
        boss_arm_next_step();
    }
}

// Boss1 entry state: Boss context already places it at (0,128) with these boxes.
async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(28fx);   // setHurtbox(56,56)
    set_hitbox(25fx);    // setHitbox(50,50)

    // !E 96/120/4.0f; !N 112/120/6.0f; !H 112/90/7.0f; !L 118/60/8.0f
    var shots: int = 96;
    var interval: int = 120;
    var target: fx = 4fx;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_NORMAL {
        shots = 112;
        target = 6fx;
    } else if rank == RANK_HARD {
        shots = 112;
        interval = 90;
        target = 7fx;
    } else if rank == RANK_LUNATIC {
        shots = 118;
        interval = 60;
        target = 8fx;
    }

    wait(60);   // source intro wait(60) before the first Boss1_at call
    loop {
        boss_fire(shots, target);   // Boss1_352: @Boss1_at()
        wait(interval);             // !E/N 120, !H 90, !L 60
        boss_begin_rand();          // moveRand(60, 4, 1.9f)
        boss_wait_move(60);         // wait(60) during the move
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(BOSS_X, BOSS_Y, 21000, 0, 0, 0, boss_main);   // lifeSet(21000)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
